import json
import os
import sys
import tempfile
from config import load_config, merge


def test_merge_basic():
    base = {"a": 1, "b": 2}
    other = {"b": 3, "c": 4}
    result = merge(base, other)
    assert result == {"a": 1, "b": 3, "c": 4}


def test_merge_nested():
    base = {"nested": {"x": 1, "y": 2}}
    other = {"nested": {"y": 3, "z": 4}, "other": 5}
    result = merge(base, other)
    assert result == {"nested": {"x": 1, "y": 3, "z": 4}, "other": 5}


def test_merge_list_replacement():
    base = {"items": [1, 2, 3]}
    other = {"items": [4, 5]}
    result = merge(base, other)
    assert result == {"items": [4, 5]}


def test_load_config_defaults_only():
    # Create a temporary defaults file
    with tempfile.NamedTemporaryFile(mode='w', suffix='.json', delete=False) as f:
